diff --git a/specs/2/SPEC.md b/specs/2/SPEC.md
new file mode 100644
index 0000000..8610bb5
--- /dev/null
+++ b/specs/2/SPEC.md
@@ -0,0 +1,31 @@
+# Spec 2: Splitting a damage charge loses a cent
+
+## Outcome
+
+When a damage charge is shared between borrowers, every penny is billed to someone. The shares add up to the charge exactly, so charge D-301 (£33.33 between two borrowers) bills £16.67 and £16.66, not £16.66 twice.
+
+## Requirements
+
+- The system shall return shares from `splitCharge` that add up to exactly the charge, in integer cents.
+- When a charge does not divide evenly, the system shall give one extra cent to each of the first (charge mod borrowers) borrowers, in order, so no two shares differ by more than one cent.
+- If the charge is smaller than the number of borrowers, the system shall bill one cent each to the first borrowers and nothing to the rest.
+- The system shall make `bun run desk split` print shares that add up to the charge, because it prints the shares `splitCharge` returns.
+
+## Must not change
+
+- Amounts stay integer cents; no floats.
+- An even charge still splits into equal shares.
+- One borrower still pays the whole charge.
+- A negative charge, a non-integer charge, or fewer than one borrower is still refused with an error.
+- Nothing under `src/auth/` is touched.
+
+## Out of scope
+
+- Weighted or unequal splits.
+- Changing how the desk formats money.
+- Fee rules other than damage-charge splitting (late fees, reservations, borrowing).
+
+## Done when
+
+- The new tests in `tests/fees/split.test.ts` pass and the existing tests still pass.
+- `bun run gate` exits 0.
diff --git a/src/fees/split.ts b/src/fees/split.ts
index 63e6c20..a5ba674 100644
--- a/src/fees/split.ts
+++ b/src/fees/split.ts
@@ -3,5 +3,6 @@ export function splitCharge(totalCents: number, ways: number): number[] {
   if (!Number.isInteger(totalCents) || totalCents < 0) throw new Error("totalCents must be a whole number of cents");
   if (!Number.isInteger(ways) || ways < 1) throw new Error("ways must be at least 1");
   const share = Math.floor(totalCents / ways);
-  return Array.from({ length: ways }, () => share);
+  const extra = totalCents % ways;
+  return Array.from({ length: ways }, (_, i) => share + (i < extra ? 1 : 0));
 }
diff --git a/tests/fees/split.test.ts b/tests/fees/split.test.ts
index 936c6bf..f033d47 100644
--- a/tests/fees/split.test.ts
+++ b/tests/fees/split.test.ts
@@ -9,6 +9,24 @@ test("one borrower pays the whole charge", () => {
   expect(splitCharge(3333, 1)).toEqual([3333]);
 });

+test("shares add up to the charge exactly", () => {
+  for (const [total, ways] of [[3333, 2], [1000, 3], [1, 7], [9999, 4], [0, 3]]) {
+    const shares = splitCharge(total, ways);
+    expect(shares).toHaveLength(ways);
+    expect(shares.reduce((a, b) => a + b, 0)).toBe(total);
+  }
+});
+
+test("the leftover cents go one each to the first borrowers", () => {
+  expect(splitCharge(3333, 2)).toEqual([1667, 1666]);
+  expect(splitCharge(1000, 3)).toEqual([334, 333, 333]);
+  expect(splitCharge(1001, 3)).toEqual([334, 334, 333]);
+});
+
+test("a charge smaller than the number of borrowers bills one cent to the first ones", () => {
+  expect(splitCharge(2, 3)).toEqual([1, 1, 0]);
+});
+
 test("a negative charge is refused", () => {
   expect(() => splitCharge(-1, 2)).toThrow();
 });

